 * EVM chain ID this signer is scoped to (1 = mainnet, 11155111 =
 * Sepolia, ...) — the value carried by `Blockchain.ethereum(_:)`.
 */
public protocol EthereumSignerFfiProtocol: AnyObject, Sendable {
    
