enum Slip39ErrorFfi: Swift.Error, Equatable, Hashable, Codable, Foundation.LocalizedError {

    
    
    case UnknownWord(word: String
    )
    case InvalidChecksum
    case UnsupportedLength(count: UInt32
    )
    case InvalidShare(reason: String
    )
    case InvalidSet(reason: String
    )
    case WrongShareCount(reason: String
    )
    case InvalidDigest
    case InvalidPassphrase
    case Cancelled

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension Slip39ErrorFfi: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSlip39ErrorFfi: FfiConverterRustBuffer {
    typealias SwiftType = Slip39ErrorFfi

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Slip39ErrorFfi {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .UnknownWord(
            word: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidChecksum
        case 3: return .UnsupportedLength(
            count: try FfiConverterUInt32.read(from: &buf)
            )
        case 4: return .InvalidShare(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .InvalidSet(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .WrongShareCount(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .InvalidDigest
        case 8: return .InvalidPassphrase
        case 9: return .Cancelled

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Slip39ErrorFfi, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .UnknownWord(word):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(word, into: &buf)
            
        
        case .InvalidChecksum:
            writeInt(&buf, Int32(2))
        
        
        case let .UnsupportedLength(count):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(count, into: &buf)
            
        
        case let .InvalidShare(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .InvalidSet(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .WrongShareCount(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .InvalidDigest:
            writeInt(&buf, Int32(7))
        
        
        case .InvalidPassphrase:
            writeInt(&buf, Int32(8))
        
        
        case .Cancelled:
            writeInt(&buf, Int32(9))
        
        }
    }
}


