    return try!  FfiConverterUInt64.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_walletkit_ffi_fn_func_bitcoin_estimate_vsize(
        FfiConverterSequenceTypeBitcoinInputKindFfi.lower(inputKinds),
        FfiConverterSequenceData.lower(outputScriptPubkeys),uniffiCallStatus
    )
})
