private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_walletkit_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_walletkit_ffi_checksum_func_aptos_transaction_hash() != 34995) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_walletkit_ffi_checksum_func_bitcoin_decode_transaction() != 53571) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_walletkit_ffi_checksum_func_bitcoin_fingerprint() != 12660) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_walletkit_ffi_checksum_func_bitcoin_build_unsigned_psbt() != 40719) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_walletkit_ffi_checksum_func_bitcoin_estimate_vsize() != 22173) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_walletkit_ffi_checksum_func_bitcoin_psbt_fee() != 16600) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_walletkit_ffi_checksum_func_bitcoin_psbt_input_derivations() != 64725) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_walletkit_ffi_checksum_func_cardano_account_xpub() != 46260) {
        return InitializationResult.apiChecksumMismatch
    }
